static parse(turtle: string): Vocabulary {
  const prefixes: Record<string, string> = {};
  const quads = new Parser().parse(turtle, null, (prefix, namespace) => {
    prefixes[prefix] = namespace.value;
  });
  return new Vocabulary(quads, prefixes);

