@prefix skos: <http://www.w3.org/2004/02/skos/core#>.
@prefix : <https://example.com/vocabulary#>.

:provider a skos:Concept;
    skos:prefLabel "Provider"@es;
    skos:definition "Quien sirve el modelo."@es.
:harness a skos:Concept;
    skos:prefLabel "Harness"@es;
    skos:definition "Un provider que corre un agente."@es;
    skos:broader :provider.

